import json

def process(order):
    if order["total"] < 0:
        raise ValueError("invalid total")
    # ... idempotent work keyed on order["id"] ...

def handler(event, context):
    failures = []
    for record in event["Records"]:
        try:
            process(json.loads(record["body"]))
        except Exception:
            failures.append({"itemIdentifier": record["messageId"]})
    return {"batchItemFailures": failures}   # only these return to the queue

if __name__ == "__main__":
    batch = {"Records": [{"messageId": "m1", "body": '{"id": 1, "total": 5}'},
                         {"messageId": "m2", "body": '{"id": 2, "total": -1}'}]}
    print(handler(batch, None))   # {'batchItemFailures': [{'itemIdentifier': 'm2'}]}

