import random, time, uuid
import boto3
from botocore.config import Config
from botocore.exceptions import ClientError
cfg = Config(retries={"mode": "adaptive", "max_attempts": 8}, connect_timeout=2, read_timeout=10)
ec2 = boto3.client("ec2", region_name="eu-west-1", config=cfg)
token = str(uuid.uuid4())   # ec2.run_instances(..., ClientToken=token): safe to retry

def full_jitter(op, attempts=5, base=0.1, cap=5.0, codes=("ThrottlingException",)):
    for n in range(attempts):
        try:
            return op()
        except ClientError as e:
            if e.response["Error"]["Code"] not in codes or n == attempts - 1:
                raise
            time.sleep(random.uniform(0, min(cap, base * 2 ** n)))

throttle = ClientError({"Error": {"Code": "ThrottlingException"}}, "PutItem")
outcomes = iter([throttle, throttle, "ok"])
def flaky():
    r = next(outcomes)
    if isinstance(r, Exception):
        raise r
    return r
print(full_jitter(flaky))   # ok  (after two throttled attempts)
